import{J as e,n as t,ot as n,q as r}from"./chunks/framework.kShLxllr.js";var i=JSON.parse(`{"title":"Class: NativeNetwork","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: NativeNetwork"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/native-network/classes/NativeNetwork"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/native-network/classes/NativeNetwork"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/native-network/src"}},"headers":[],"relativePath":"api/@jsprismarine/native-network/classes/NativeNetwork.md","filePath":"api/@jsprismarine/native-network/classes/NativeNetwork.md","lastUpdated":1794453735000}`),a={name:`api/@jsprismarine/native-network/classes/NativeNetwork.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/native-network</a> / NativeNetwork</p><h1 id="class-nativenetwork" tabindex="-1">Class: NativeNetwork <a class="header-anchor" href="#class-nativenetwork" aria-label="Permalink to “Class: NativeNetwork”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f1978925a4fa1c62a88194796e34b7c429ca6f11/packages/native-network/src/NativeNetwork.ts#L62" target="_blank" rel="noreferrer">packages/native-network/src/NativeNetwork.ts:62</a></p><p>The native library, loaded once per thread, and that thread&#39;s event queue.</p><p>The library is mapped once per process, and each thread that loads it opens a queue of its own, so a worker&#39;s peer connections report to the worker. libdatachannel&#39;s threads queue events in native memory and send one datagram to a loopback socket here when the queue stops being empty. The socket&#39;s handler drains the queue and dispatches each event to the handler registered for its id, so every event reaches JavaScript on the event loop, in order, with no call from a foreign thread.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="queue" tabindex="-1">queue <a class="header-anchor" href="#queue" aria-label="Permalink to “queue”">​</a></h3><blockquote><p><code>readonly</code> <strong>queue</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f1978925a4fa1c62a88194796e34b7c429ca6f11/packages/native-network/src/NativeNetwork.ts#L80" target="_blank" rel="noreferrer">packages/native-network/src/NativeNetwork.ts:80</a></p><p>The handle of this thread&#39;s event queue, which peer connections are created on.</p><hr><h3 id="wakes" tabindex="-1">wakes <a class="header-anchor" href="#wakes" aria-label="Permalink to “wakes”">​</a></h3><blockquote><p><strong>wakes</strong>: <code>number</code> = <code>0</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f1978925a4fa1c62a88194796e34b7c429ca6f11/packages/native-network/src/NativeNetwork.ts#L66" target="_blank" rel="noreferrer">packages/native-network/src/NativeNetwork.ts:66</a></p><p>Wake datagrams received; a burst of events costs one.</p><h2 id="accessors" tabindex="-1">Accessors <a class="header-anchor" href="#accessors" aria-label="Permalink to “Accessors”">​</a></h2><h3 id="symbols" tabindex="-1">symbols <a class="header-anchor" href="#symbols" aria-label="Permalink to “symbols”">​</a></h3><h4 id="get-signature" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>symbols</strong>(): <code>NativeSymbols</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f1978925a4fa1c62a88194796e34b7c429ca6f11/packages/native-network/src/NativeNetwork.ts#L142" target="_blank" rel="noreferrer">packages/native-network/src/NativeNetwork.ts:142</a></p><p>The bound C interface.</p><h5 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h5><p><code>NativeSymbols</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="close" tabindex="-1">close() <a class="header-anchor" href="#close" aria-label="Permalink to “close()”">​</a></h3><blockquote><p><strong>close</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f1978925a4fa1c62a88194796e34b7c429ca6f11/packages/native-network/src/NativeNetwork.ts#L238" target="_blank" rel="noreferrer">packages/native-network/src/NativeNetwork.ts:238</a></p><p>Closes this thread&#39;s peer connections and its event queue. The library stays mapped, and another thread&#39;s connections and the shared ports are not touched.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="drain" tabindex="-1">drain() <a class="header-anchor" href="#drain" aria-label="Permalink to “drain()”">​</a></h3><blockquote><p><strong>drain</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f1978925a4fa1c62a88194796e34b7c429ca6f11/packages/native-network/src/NativeNetwork.ts#L191" target="_blank" rel="noreferrer">packages/native-network/src/NativeNetwork.ts:191</a></p><p>Reads every queued event and dispatches it; a read that finds the queue empty rearms the wake.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="flushlog" tabindex="-1">flushLog() <a class="header-anchor" href="#flushlog" aria-label="Permalink to “flushLog()”">​</a></h3><blockquote><p><strong>flushLog</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f1978925a4fa1c62a88194796e34b7c429ca6f11/packages/native-network/src/NativeNetwork.ts#L201" target="_blank" rel="noreferrer">packages/native-network/src/NativeNetwork.ts:201</a></p><p>Hands every queued log line to the log handler now, and keeps the other events, in order, for the next turn of the event loop. A call that failed reads the lines it logged this way without running another handler in the middle of its own failure.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="hold" tabindex="-1">hold() <a class="header-anchor" href="#hold" aria-label="Permalink to “hold()”">​</a></h3><blockquote><p><strong>hold</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f1978925a4fa1c62a88194796e34b7c429ca6f11/packages/native-network/src/NativeNetwork.ts#L181" target="_blank" rel="noreferrer">packages/native-network/src/NativeNetwork.ts:181</a></p><p>Keeps the process alive until the matching <a href="#release">NativeNetwork.release</a>.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="onlog" tabindex="-1">onLog() <a class="header-anchor" href="#onlog" aria-label="Permalink to “onLog()”">​</a></h3><blockquote><p><strong>onLog</strong>(<code>handler</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f1978925a4fa1c62a88194796e34b7c429ca6f11/packages/native-network/src/NativeNetwork.ts#L176" target="_blank" rel="noreferrer">packages/native-network/src/NativeNetwork.ts:176</a></p><p>Receives libdatachannel&#39;s log lines, when the library was loaded with a log level.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="handler" tabindex="-1">handler <a class="header-anchor" href="#handler" aria-label="Permalink to “handler”">​</a></h5><p>(<code>level</code>, <code>line</code>) =&gt; <code>void</code></p><p>Receives each line and its level.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="pointerof" tabindex="-1">pointerOf() <a class="header-anchor" href="#pointerof" aria-label="Permalink to “pointerOf()”">​</a></h3><blockquote><p><strong>pointerOf</strong>(<code>memory</code>): <code>number</code> | <code>bigint</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f1978925a4fa1c62a88194796e34b7c429ca6f11/packages/native-network/src/NativeNetwork.ts#L151" target="_blank" rel="noreferrer">packages/native-network/src/NativeNetwork.ts:151</a></p><p>The address of shared memory, for an interface call that takes a pointer.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="memory" tabindex="-1">memory <a class="header-anchor" href="#memory" aria-label="Permalink to “memory”">​</a></h5><p><code>SharedArrayBuffer</code></p><p>The memory; it must outlive every native use of the pointer.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code> | <code>bigint</code></p><p>The pointer.</p><hr><h3 id="release" tabindex="-1">release() <a class="header-anchor" href="#release" aria-label="Permalink to “release()”">​</a></h3><blockquote><p><strong>release</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f1978925a4fa1c62a88194796e34b7c429ca6f11/packages/native-network/src/NativeNetwork.ts#L186" target="_blank" rel="noreferrer">packages/native-network/src/NativeNetwork.ts:186</a></p><p>Lets the process exit once nothing holds it.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="unwatch" tabindex="-1">unwatch() <a class="header-anchor" href="#unwatch" aria-label="Permalink to “unwatch()”">​</a></h3><blockquote><p><strong>unwatch</strong>(<code>id</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f1978925a4fa1c62a88194796e34b7c429ca6f11/packages/native-network/src/NativeNetwork.ts#L168" target="_blank" rel="noreferrer">packages/native-network/src/NativeNetwork.ts:168</a></p><p>Stops sending an id&#39;s events anywhere.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id" tabindex="-1">id <a class="header-anchor" href="#id" aria-label="Permalink to “id”">​</a></h5><p><code>number</code></p><p>The peer connection or data channel.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="watch" tabindex="-1">watch() <a class="header-anchor" href="#watch" aria-label="Permalink to “watch()”">​</a></h3><blockquote><p><strong>watch</strong>(<code>id</code>, <code>handler</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f1978925a4fa1c62a88194796e34b7c429ca6f11/packages/native-network/src/NativeNetwork.ts#L160" target="_blank" rel="noreferrer">packages/native-network/src/NativeNetwork.ts:160</a></p><p>Sends the events of one id to a handler, until <a href="#unwatch">NativeNetwork.unwatch</a>.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id-1" tabindex="-1">id <a class="header-anchor" href="#id-1" aria-label="Permalink to “id”">​</a></h5><p><code>number</code></p><p>The peer connection or data channel.</p><h5 id="handler-1" tabindex="-1">handler <a class="header-anchor" href="#handler-1" aria-label="Permalink to “handler”">​</a></h5><p><a href="./../#nativeeventhandler"><code>NativeEventHandler</code></a></p><p>Receives its events in order.</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="load" tabindex="-1">load() <a class="header-anchor" href="#load" aria-label="Permalink to “load()”">​</a></h3><blockquote><p><code>static</code> <strong>load</strong>(<code>options?</code>): <code>Promise</code>&lt;<code>NativeNetwork</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f1978925a4fa1c62a88194796e34b7c429ca6f11/packages/native-network/src/NativeNetwork.ts#L96" target="_blank" rel="noreferrer">packages/native-network/src/NativeNetwork.ts:96</a></p><p>Loads the library and opens this thread&#39;s event queue, the first time it is called on a thread.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p>The library file and log level; the defaults find the installed build and log warnings and worse. libdatachannel takes the level once per process, from the first load.</p><h6 id="loglevel" tabindex="-1">logLevel? <a class="header-anchor" href="#loglevel" aria-label="Permalink to “logLevel?”">​</a></h6><p><code>number</code></p><h6 id="path" tabindex="-1">path? <a class="header-anchor" href="#path" aria-label="Permalink to “path?”">​</a></h6><p><code>string</code></p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>NativeNetwork</code>&gt;</p><p>The loaded library.</p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>When the library cannot be found, loaded, or speaks another interface.</p><hr><h3 id="loaded" tabindex="-1">loaded() <a class="header-anchor" href="#loaded" aria-label="Permalink to “loaded()”">​</a></h3><blockquote><p><code>static</code> <strong>loaded</strong>(): <code>NativeNetwork</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f1978925a4fa1c62a88194796e34b7c429ca6f11/packages/native-network/src/NativeNetwork.ts#L137" target="_blank" rel="noreferrer">packages/native-network/src/NativeNetwork.ts:137</a></p><p>The loaded library, or undefined before <a href="#load">NativeNetwork.load</a>.</p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to “Returns”">​</a></h4><p><code>NativeNetwork</code> | <code>undefined</code></p>`,130)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};